export function categoryLabel(category, language) {
  if (!category) return ''
  const id = category.slug || category.id
  return categoryNames[language]?.[id] || (language === 'en' ? category.name_en : category.name_so) || category.name_so
}

export function LanguageProvider({ children }) {
  const [language, setLanguage] = useState(() => {
    const saved = localStorage.getItem('heladeeg-language')
    return supportedLanguages.includes(saved) ? saved : 'en'
  })
  useEffect(() => {
    localStorage.setItem('heladeeg-language', language)
    document.documentElement.lang = language
    document.documentElement.dir = language === 'ar' ? 'rtl' : 'ltr'
  }, [language])
  const value = useMemo(() => ({
    language,
    setLanguage,
    t: (key) => translations[language]?.[key] ?? pageTranslations[language]?.[key] ?? extraTranslations[language]?.[key] ?? screenTranslations[language]?.[key] ?? requestFormTranslations[language]?.[key] ?? resetTranslations[language]?.[key] ?? translations.en[key] ?? pageTranslations.en[key] ?? extraTranslations.en[key] ?? screenTranslations.en[key] ?? requestFormTranslations.en[key] ?? resetTranslations.en[key] ?? key,
  }), [language])
  return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>
}

export function useLanguage() {
  const value = useContext(LanguageContext)
  if (!value) throw new Error('useLanguage must be used within LanguageProvider')
  return value
}
